# relations: P mother Q; Q father R; R daughter S; S female (sister)
parent={'R':{'Q','S'},'Q':{'P'}}
gender={'P':'F','Q':'M','S':'F'}
spouse_of_S=[x for x in parent['R'] if x!='S'][0]
assert gender[spouse_of_S]=='M'
rel = "Husband’s mother" if 'P' in parent[spouse_of_S] and gender['P']=='F' else None
opts={'A':'Mother','B':'Sister’s daughter','C':'Husband’s mother','D':'Sister’s husband'}
assert rel==opts['C']
for k in 'ABD': assert rel!=opts[k]

syn={('Control','Domination'),('Descend','Fall')}
ant={('Creation','Destruction'),('Liberation','Slavery')}
rel=lambda p:'syn' if p in syn else ('ant' if p in ant else 'other')
opts={'A':('Descend','Fall'),'B':('Manipulation','Deceive'),'C':('Creation','Destruction'),'D':('Liberation','Slavery')}
t=rel(('Control','Domination'))
fits=[k for k,v in opts.items() if rel(v)==t]
assert fits==['A']

g=lambda s:tuple(ord(s[i+1])-ord(s[i]) for i in range(2))
opts={'A':'IKN','B':'MPR','C':'CFH','D':'EHJ'}
gs={k:g(v) for k,v in opts.items()}
odd=[k for k in opts if list(gs.values()).count(gs[k])==1]
assert odd==['A']

import re
e='19 + 125 / 25 - 100 / 5 + 4 * 3'
def sw(a,b): return eval(re.sub(r'\b(%s|%s)\b'%(a,b),lambda m:b if m.group(0)==a else a,e))
opts={'A':('125','100'),'B':('25','5'),'C':('19','4'),'D':('4','5')}
fits=[k for k,v in opts.items() if sw(*v)==52]
assert fits==['B']

s='__C_DC__CC__'
opts={'A':'DDCCCDD','B':'CCDCCDD','C':'DCCCDCC','D':'CDCCDDC'}
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in s)
def periodic(t):
    return any(all(t[i]==t[i%p] for i in range(len(t))) for p in range(2,5))
fits=[k for k,v in opts.items() if periodic(fill(v))]
assert fits==['D']

from itertools import permutations
ring=['B','V','M','P']
res=set()
for p in permutations(ring):
    if p[0]!='B': continue
    nxt={p[i]:p[(i+1)%4] for i in range(4)}
    if nxt['B']=='V' and nxt['M']=='P': res.add(p[2])
assert res=={'M'}
opts={'A':'M','B':'V','C':'K','D':'P'}
assert opts['A'] in res
for k in 'BCD': assert opts[k] not in res

