def nxt(t):
    a=chr((ord(t[0])-65+2)%26+65); b=chr((ord(t[1])-65+2)%26+65)
    return a+b+str(int(t[2:])+2)
s=['NW17']
for i in range(4): s.append(nxt(s[-1]))
assert s[:4]==['NW17','PY19','RA21','TC23']
opts={'A':'XD24','B':'WF23','C':'VE25','D':'WD24'}
assert s[4]==opts['C']
for k in 'ABD': assert s[4]!=opts[k]

s='QUA_TO_ANT_UAN_KU_NT'
opts={'A':'NUTMA','B':'NUMTA','C':'NULTA','D':'NUTAM'}
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in s)
def ok(t):
    bl=[t[i:i+5] for i in range(0,20,5)]
    return all(b[1:]=='UANT' for b in bl) and all(ord(bl[i][0])-ord(bl[i+1][0])==2 for i in range(3))
